/**
 * Interprets the TASKS_NON_ADMIN_DELETE_PERMISSION org preference.
 *
 * The preference is a raw string with four recognised values that widen
 * strictly: none < created < assigned < all.
 *
 * An org that never configured the setting has no stored row, and that
 * unconfigured state resolves to "assigned". A value that is present but
 * unrecognised is treated as a misconfiguration and fails closed to "none"
 * instead, so a typo or corrupt value can never widen permissions.
 */

import { idsEqual } from 'src/utils/general';
import { logger } from 'src/utils/logger';

export type TaskDeletePermission = 'none' | 'created' | 'assigned' | 'all';

const RECOGNISED_MODES: readonly TaskDeletePermission[] = [
  'none',
  'created',
  'assigned',
  'all',
];

const UNCONFIGURED_DEFAULT: TaskDeletePermission = 'assigned';
const INVALID_VALUE_FALLBACK: TaskDeletePermission = 'none';

// The gate runs for every task row on every re-render, so a fallback would be
// reported on each call. Report each distinct value once per page load instead.
const reportedValues = new Set<string>();

function reportFallback(
  value: unknown,
  isUnconfigured: boolean,
  resolvedMode: TaskDeletePermission,
): void {
  const seenKey = `${typeof value}:${String(value)}`;
  if (reportedValues.has(seenKey)) {
    return;
  }
  reportedValues.add(seenKey);

  // An unconfigured org is the normal state, so it is not worth a warning. A
  // value that is present but unrecognised is worth surfacing.
  if (isUnconfigured) {
    logger.debug(`[TaskDeletePermission] TASKS_NON_ADMIN_DELETE_PERMISSION is not configured, defaulting to "${resolvedMode}"`);
    return;
  }
  logger.warn(`[TaskDeletePermission] TASKS_NON_ADMIN_DELETE_PERMISSION is unrecognised (${typeof value} ${JSON.stringify(value)}), falling back to "${resolvedMode}" (admin-only)`);
}

export function toTaskDeletePermission(value: unknown): TaskDeletePermission {
  const mode = String(value ?? '')
    .trim()
    .toLowerCase();
  if ((RECOGNISED_MODES as readonly string[]).includes(mode)) {
    return mode as TaskDeletePermission;
  }

  // Blank in any form - key absent, null, empty or whitespace-only - means the
  // org never set a value; anything else is a value we cannot interpret.
  const isUnconfigured = mode === '';
  const resolvedMode = isUnconfigured
    ? UNCONFIGURED_DEFAULT
    : INVALID_VALUE_FALLBACK;
  reportFallback(value, isUnconfigured, resolvedMode);
  return resolvedMode;
}

// Exported for tests: the report dedupe is module state that must not leak
// between cases.
export function resetTaskDeletePermissionReporting(): void {
  reportedValues.clear();
}

/**
 * A user id as it can reach this layer: the backend types user ids as integers
 * (`assigned_to_user_id?: number` in the generated task models), while values
 * that have been through user_details, storage or a cache round-trip arrive as
 * the string form of that integer. Nullable because created_by is nullable.
 */
export type UserIdValue = number | string | null | undefined;

export interface TaskDeleteGateInput {
  isAdmin: boolean;
  /** Raw TASKS_NON_ADMIN_DELETE_PERMISSION value: one of the four modes. */
  permission: string | null | undefined;
  /** The task's created_by. Null for system-created tasks - nobody owns them. */
  taskCreatedBy: UserIdValue;
  /** The logged-in user's id, which getUserDetailFromkey hands over as a string. */
  currentUserId: UserIdValue;
  /** tasks.store.isHasAccess(row): the task is assigned to somebody else. */
  taskBelongsToSomeoneElse: boolean;
}

/**
 * The single delete predicate shared by every task surface (tasks list,
 * board card, and the task panel inside the document screens).
 *
 * Creating a task always earns the right to delete it, so the creator rule
 * fires in both "created" and "assigned".
 *
 * The creator comparison must go through idsEqual, never ===: the backend
 * sends created_by as an integer while the current user's id reaches the
 * client as a string, so a strict comparison would hide delete from every
 * creator. idsEqual also never matches an empty value, so a task with no
 * recorded creator belongs to nobody - exactly how the backend treats it.
 * A task nobody is assigned to yields taskBelongsToSomeoneElse=true for a
 * non-admin and is likewise refused server-side.
 */
export function canDeleteTaskRow({
  isAdmin,
  permission,
  taskCreatedBy,
  currentUserId,
  taskBelongsToSomeoneElse,
}: TaskDeleteGateInput): boolean {
  if (isAdmin) {
    return true;
  }

  const mode = toTaskDeletePermission(permission);
  if (mode === 'all') {
    return true;
  }
  if (mode === 'none') {
    return false;
  }

  if (idsEqual(taskCreatedBy, currentUserId)) {
    return true;
  }

  return mode === 'assigned' && !taskBelongsToSomeoneElse;
}
